using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Reflection;
using Gum.Forms.Controls;
using Gum.Forms.Data;
using Gum.GueDeriving;
using Gum.Mvvm;
using Gum.Wireframe;
using Shouldly;
using Xunit;
using Xunit.Abstractions;

namespace MonoGameGum.Tests.Forms;

/// <summary>
/// Every public read/write property of a simple type on every Forms control and every standard
/// runtime, generated by reflection: a binding must deliver the same value direct assignment does.
/// A property whose direct assignment does not round-trip (coerced, clamped, needs other state) is
/// skipped, since binding cannot be expected to do better.
/// </summary>
public class BindablePropertyMatrixTests : BaseTestClass
{
    private readonly ITestOutputHelper _output;

    public BindablePropertyMatrixTests(ITestOutputHelper output)
    {
        _output = output;
    }

    public class ValueViewModel<T> : ViewModel
    {
        public T Value { get => Get<T>(); set => Set(value); }
    }

    private static readonly Type[] SimpleTypes = { typeof(bool), typeof(int), typeof(float), typeof(double), typeof(string) };

    private static IEnumerable<Type> ConstructibleTypes(Type baseType, Assembly assembly, string ns) =>
        assembly.GetTypes()
            .Where(type => type.IsPublic && !type.IsAbstract && !type.IsGenericTypeDefinition
                && type.Namespace == ns
                && baseType.IsAssignableFrom(type)
                && type.GetConstructor(Type.EmptyTypes) != null
                && type.GetCustomAttribute<ObsoleteAttribute>() == null)
            .OrderBy(type => type.Name);

    private static IEnumerable<PropertyInfo> BindableProperties(Type type) =>
        type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(property => property.CanRead && property.GetSetMethod() != null
                && property.GetIndexParameters().Length == 0
                && SimpleTypes.Contains(property.PropertyType)
                && property.Name != nameof(GraphicalUiElement.BindingContext)
                && property.GetCustomAttribute<ObsoleteAttribute>() == null)
            .OrderBy(property => property.Name);

    private static object NextValue(object? current, Type type)
    {
        if (type == typeof(bool)) { return !(bool)current!; }
        if (type == typeof(int)) { return (int)current! + 1; }
        if (type == typeof(float)) { return (float)current! + 1; }
        if (type == typeof(double)) { return (double)current! + 1; }
        return (current as string ?? "") + "bound";
    }

    private static object? TryCreate(Type type)
    {
        try
        {
            return Activator.CreateInstance(type);
        }
        catch
        {
            return null;
        }
    }

    /// <summary>Returns the value to bind, or null when direct assignment does not round-trip.</summary>
    private static object? RoundTrippingValue(Type ownerType, PropertyInfo property)
    {
        object? probe = TryCreate(ownerType);
        // A control built without a Visual has nowhere to keep a BindingContext.
        if (probe == null || probe is FrameworkElement { Visual: null })
        {
            return null;
        }
        try
        {
            object? original = property.GetValue(probe);
            object next = NextValue(original, property.PropertyType);
            property.SetValue(probe, next);
            if (!Equals(property.GetValue(probe), next))
            {
                return null;
            }
            property.SetValue(probe, original);
            return Equals(property.GetValue(probe), original) ? next : null;
        }
        catch
        {
            return null;
        }
    }

    private static object CreateViewModel(Type valueType, object? value)
    {
        object viewModel = Activator.CreateInstance(typeof(ValueViewModel<>).MakeGenericType(valueType))!;
        viewModel.GetType().GetProperty("Value")!.SetValue(viewModel, value);
        return viewModel;
    }

    private static object? ReadViewModel(object viewModel) => viewModel.GetType().GetProperty("Value")!.GetValue(viewModel);

    private static void WriteViewModel(object viewModel, object? value) => viewModel.GetType().GetProperty("Value")!.SetValue(viewModel, value);

    [Fact]
    public void FormsControls_EveryBindableProperty_FollowsViewModel()
    {
        List<string> failures = new();
        int checkedCount = 0;

        foreach (Type controlType in ConstructibleTypes(typeof(FrameworkElement), typeof(FrameworkElement).Assembly, "Gum.Forms.Controls"))
        {
            foreach (PropertyInfo property in BindableProperties(controlType))
            {
                object? next = RoundTrippingValue(controlType, property);
                if (next == null)
                {
                    continue;
                }
                checkedCount++;
                string caseName = $"{controlType.Name}.{property.Name}";
                try
                {
                    FrameworkElement control = (FrameworkElement)Activator.CreateInstance(controlType)!;
                    object? original = property.GetValue(control);
                    object viewModel = CreateViewModel(property.PropertyType, next);
                    control.BindingContext = viewModel;
                    control.SetBinding(property.Name, new Binding("Value") { Mode = BindingMode.OneWay });

                    if (!Equals(property.GetValue(control), next))
                    {
                        failures.Add($"{caseName}: initial {property.GetValue(control)} expected {next}");
                        continue;
                    }
                    WriteViewModel(viewModel, original);
                    if (!Equals(property.GetValue(control), original))
                    {
                        failures.Add($"{caseName}: after change {property.GetValue(control)} expected {original}");
                    }
                }
                catch (Exception exception)
                {
                    failures.Add($"{caseName}: threw {exception.GetType().Name} {exception.Message}");
                }
            }
        }

        _output.WriteLine($"Forms properties checked: {checkedCount}");
        checkedCount.ShouldBeGreaterThan(50);
        failures.ShouldBeEmpty(string.Join(Environment.NewLine, failures));
    }

    [Fact]
    public void FormsControls_EveryNotifyingProperty_TwoWayWritesBackToViewModel()
    {
        List<string> failures = new();
        int checkedCount = 0;

        foreach (Type controlType in ConstructibleTypes(typeof(FrameworkElement), typeof(FrameworkElement).Assembly, "Gum.Forms.Controls"))
        {
            foreach (PropertyInfo property in BindableProperties(controlType))
            {
                object? next = RoundTrippingValue(controlType, property);
                if (next == null)
                {
                    continue;
                }

                // Only a target that raises PropertyChanged for the property can push edits back.
                FrameworkElement probe = (FrameworkElement)Activator.CreateInstance(controlType)!;
                bool raises = false;
                ((INotifyPropertyChanged)probe).PropertyChanged += (_, args) =>
                {
                    if (args.PropertyName == property.Name)
                    {
                        raises = true;
                    }
                };
                property.SetValue(probe, next);
                if (!raises)
                {
                    continue;
                }

                checkedCount++;
                string caseName = $"{controlType.Name}.{property.Name}";
                try
                {
                    FrameworkElement control = (FrameworkElement)Activator.CreateInstance(controlType)!;
                    object? original = property.GetValue(control);
                    object viewModel = CreateViewModel(property.PropertyType, original);
                    control.BindingContext = viewModel;
                    control.SetBinding(property.Name, new Binding("Value") { Mode = BindingMode.TwoWay });

                    property.SetValue(control, next);

                    if (!Equals(ReadViewModel(viewModel), next))
                    {
                        failures.Add($"{caseName}: view model {ReadViewModel(viewModel)} expected {next}");
                    }
                }
                catch (Exception exception)
                {
                    failures.Add($"{caseName}: threw {exception.GetType().Name} {exception.Message}");
                }
            }
        }

        _output.WriteLine($"Forms notifying properties checked: {checkedCount}");
        checkedCount.ShouldBeGreaterThan(10);
        failures.ShouldBeEmpty(string.Join(Environment.NewLine, failures));
    }

    [Fact]
    public void StandardRuntimes_EveryBindableProperty_FollowsViewModel()
    {
        List<string> failures = new();
        int checkedCount = 0;

        foreach (Type runtimeType in ConstructibleTypes(typeof(GraphicalUiElement), typeof(TextRuntime).Assembly, "Gum.GueDeriving"))
        {
            foreach (PropertyInfo property in BindableProperties(runtimeType))
            {
                object? next = RoundTrippingValue(runtimeType, property);
                if (next == null)
                {
                    continue;
                }
                checkedCount++;
                string caseName = $"{runtimeType.Name}.{property.Name}";
                try
                {
                    GraphicalUiElement runtime = (GraphicalUiElement)Activator.CreateInstance(runtimeType)!;
                    object? original = property.GetValue(runtime);
                    object viewModel = CreateViewModel(property.PropertyType, next);
                    runtime.BindingContext = viewModel;
                    runtime.SetBinding(property.Name, "Value");

                    if (!Equals(property.GetValue(runtime), next))
                    {
                        failures.Add($"{caseName}: initial {property.GetValue(runtime)} expected {next}");
                        continue;
                    }
                    WriteViewModel(viewModel, original);
                    if (!Equals(property.GetValue(runtime), original))
                    {
                        failures.Add($"{caseName}: after change {property.GetValue(runtime)} expected {original}");
                    }
                }
                catch (Exception exception)
                {
                    failures.Add($"{caseName}: threw {exception.GetType().Name} {exception.Message}");
                }
            }
        }

        _output.WriteLine($"Runtime properties checked: {checkedCount}");
        checkedCount.ShouldBeGreaterThan(20);
        failures.ShouldBeEmpty(string.Join(Environment.NewLine, failures));
    }
}
